export function paymentStatusLabel(status: "pending" | "done") {
  switch (status) {
    case "pending":
      return "Pending";
    case "done":
      return "Done";
  }
}

export function shippingStatusLabel(status: "pending" | "done") {
  switch (status) {
    case "pending":
      return "Pending";
    case "done":
      return "Done";
  }
}
